select a.*,departmentName from(
SELECT  application_form.id,order_number,date,sort,user_id,complete_status,name,sort_two,reason,department,circulation_boss,robot from application_form  LEFT JOIN `user`  on application_form.user_id = `user`.id
) as a LEFT JOIN department on a.department = department.id
    where a.id in

        #{applicationForms.id,jdbcType=INTEGER}

    order by date desc

select c.*,departmentName from (select b.*,name,department from ( select application_form.* from( select app_form_id from take_order where user = #{ckId}
union select app_form_id from log where manager = #{ckId}
) as a LEFT JOIN application_form on application_form.id = app_form_id) as b LEFT JOIN user on b.user_id = user.id) as c LEFT JOIN department on department.id = c.department where complete_status !=2
and sort = #{sort}
and sort in
1, 0, 2, 3, 4,
and circulation_boss = 1 ORDER BY FIELD(complete_status,3,5,0,6,1,7,2,4), SUBSTRING_INDEX(order_number, '_', -1)desc limit #{begin},#{size}

