select distinct user_id, userName, department, name,departmentName from (
        select * from (select  user_id,userName,department,name,application_form.id as appId,circulation_boss from application_form left join user on user_id = user.id where complete_status !=2 and application_form.sort=#{sort} and circulation_boss =1) as a
            LEFT JOIN department on department.id = a.department
) as b left join take_order on take_order.app_form_id = b.appId

            where take_order.user = #{ckId}

